from z3 import *
import json

# Define locations
locations = [
    {"id": "orchid_garden", "cost": 15, "duration": 90, "open": 510, "close": 1140, "showtimes": []},
    {"id": "jewel_changi", "cost": 0, "duration": 60, "open": 600, "close": 1440, "showtimes": []},
    {"id": "spectra", "cost": 0, "duration": 15, "open": 1185, "close": 1290, "showtimes": [1200, 1260]},
    {"id": "adventure_cove", "cost": 40, "duration": 180, "open": 600, "close": 1020, "showtimes": []}
]

# Travel times matrix
travel_times = {
    "orchid_garden": {"jewel_changi": 59, "spectra": 24, "adventure_cove": 25},
    "jewel_changi": {"orchid_garden": 59, "spectra": 51, "adventure_cove": 64},
    "spectra": {"orchid_garden": 24, "jewel_changi": 51, "adventure_cove": 23},
    "adventure_cove": {"orchid_garden": 25, "jewel_changi": 64, "spectra": 23}
}

day_start = 540  # 09:00
day_end = 765    # 12:45
max_budget = 15

s = Solver()

# Decision variables
visited = {loc["id"]: Bool(f"visited_{loc['id']}") for loc in locations}
start = {loc["id"]: Int(f"start_{loc['id']}") for loc in locations}
end = {loc["id"]: Int(f"end_{loc['id']}") for loc in locations}

# Mandatory visits
s.add(visited["orchid_garden"])
s.add(visited["jewel_changi"])

# Budget constraint
total_cost = Sum([If(visited[loc["id"]], loc["cost"], 0) for loc in locations])
s.add(total_cost <= max_budget)

for loc in locations:
    lid = loc["id"]
    dur = loc["duration"]

    # Time bounds if visited
    s.add(Implies(visited[lid], And(
        start[lid] >= loc["open"],
        end[lid] <= loc["close"],
        end[lid] == start[lid] + dur,
        start[lid] >= day_start,
        end[lid] <= day_end
    )))

    # Showtimes constraint
    if loc["showtimes"]:
        show_cond = Or([start[lid] == st for st in loc["showtimes"]])
        s.add(Implies(visited[lid], show_cond))

# No overlap and travel time constraints
loc_ids = [loc["id"] for loc in locations]
for i in range(len(loc_ids)):
    for j in range(len(loc_ids)):
        if i != j:
            id1 = loc_ids[i]
            id2 = loc_ids[j]
            t_time = travel_times[id1][id2]
            # If both visited, either 1 finishes + travel <= 2, or 2 finishes + travel <= 1
            s.add(Implies(
                And(visited[id1], visited[id2]),
                Or(end[id1] + t_time <= start[id2], end[id2] + t_time <= start[id1])
            ))

if s.check() == sat:
    m = s.model()
    result = []
    for loc in locations:
        lid = loc["id"]
        if is_true(m[visited[lid]]):
            result.append({
                "location_id": lid,
                "start": m[start[lid]].as_long(),
                "end": m[end[lid]].as_long()
            })
    print(json.dumps(result))
else:
    print("UNSAT")
